properties.definition:
type Product {
  sku: ID!
  title: String!
  priceMinor: Int!
  available: Boolean!
}

type Query {
  product(sku: ID!): Product
  products(category: String, first: Int = 20): [Product!]!
}

# Frames are newline-delimited JSON, client-initiated subscribe then server push.
-> {"op":"subscribe","cartId":"c_123"}
<- {"op":"cart.updated","cartId":"c_123","lines":3,"totalMinor":8940}
<- {"op":"stock.changed","sku":"SKU-9","available":false}

syntax = "proto3";
package acme.payments.v1;

service Payments {
  rpc Authorize(AuthorizeRequest) returns (AuthorizeResponse);
  rpc Capture(CaptureRequest) returns (CaptureResponse);
}

message AuthorizeRequest {
  string order_id = 1;
  int64 amount_minor = 2;
  string currency = 3;
}
message AuthorizeResponse { string authorization_id = 1; }
message CaptureRequest { string authorization_id = 1; }
message CaptureResponse { bool captured = 1; }
